# iOS-hoz optimalizált, natív érzetű PWA AI chat app (Cerebras gpt-oss-120b + Exa AI)

Az alábbi példa egy komplett, magyar nyelvű, fekete hátterű, élénk pink akcentusú (Uniswap-stílusú) AI chat webappot tartalmaz. iOS-re PWA-ként optimalizált: telepíthető, splash/ikon, status bar stílus, és Safari/PWA korlátok figyelembevétele. Backend: Python (FastAPI) `main.py`. Frontend: `index.html`. A chat a Cerebras gpt-oss-120b modellel streamelve működik, és beépített keresőeszközként az Exa AI is használható (maxra állítva — erős keresési paraméterekkel). A backend egyesíti az LLM-et és a keresést: a felhasználói kérdést opcionálisan Exa-val gazdagítja, majd a kontextust a Cerebrasnak adja.

FONTOS: a kód futtatásához szükséges környezeti változók:
- CEREBRAS_API_KEY
- EXA_API_KEY

Ahol szükséges, telepítsd a csomagokat:
- pip install fastapi uvicorn sse-starlette python-multipart exa_py cerebras-cloud-sdk

## Fájl: main.py (backend, FastAPI, SSE streaming)

```python
import os
import json
import asyncio
from typing import Optional, List, Dict, Any

from fastapi import FastAPI, Request, HTTPException
from fastapi.responses import StreamingResponse, JSONResponse
from fastapi.middleware.cors import CORSMiddleware
from sse_starlette.sse import EventSourceResponse

# Cerebras SDK
from cerebras.cloud.sdk import Cerebras

# Exa AI SDK (hivatalos Python kliens)
# pip install exa_py
from exa_py import Exa

app = FastAPI(title="Magyar AI Chat PWA", version="1.0.0")

# CORS – frontendre szabaddá tesszük (igény szerint szigorítható)
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],  # állítsd be a saját domainre, ha van
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# Inicializáció – kulcsok a környezetből
CEREBRAS_API_KEY = os.environ.get("CEREBRAS_API_KEY")
EXA_API_KEY = os.environ.get("EXA_API_KEY")

if not CEREBRAS_API_KEY:
    raise RuntimeError("Hiányzik a CEREBRAS_API_KEY környezeti változó.")
if not EXA_API_KEY:
    # Exa opcionális, de a felhasználó kérte, hogy legyen „maxra állítva”
    # ha nincs kulcs, csak figyelmeztetünk és Exa nélkül futunk
    print("FIGYELEM: Hiányzik az EXA_API_KEY – a keresős kiegészítés ki lesz kapcsolva.")

cerebras_client = Cerebras(api_key=CEREBRAS_API_KEY)
exa_client = Exa(api_key=EXA_API_KEY) if EXA_API_KEY else None

SYSTEM_PROMPT = (
    "Te egy barátságos, lényegre törő, magyar nyelvű asszisztens vagy. "
    "Válaszaid legyenek tömörek, mégis hasznosak. Ha a felhasználó kérését "
    "külső hivatkozás nélkül is meg tudod válaszolni, tedd meg. Ha szükséges, "
    "a mellékelt keresési kivonatokat (Exa) használd fel kontextusként."
)

# Gyors Exa „max” keresés – agresszívebb kiterjesztés, több találat, kivonatokkal
async def exa_search_augmented_context(query: str, max_results: int = 8) -> str:
    if not exa_client:
        return ""
    try:
        # Erősebb beállítások: mély kivonat, frissesség előnyben, több találat
        results = exa_client.search_and_contents(
            query=query,
            num_results=max_results,
            use_autoprompt=True,
            # tartalom kibontás:
            include_content=True,
            summary_max_sentences=6,
            # rendezés és frissesség
            type="keyword",
            sort_by="relevance",
            recency_bias=True,
        )
        # Egyszerű, LLM-barát kontextus szintézis
        snippets = []
        for r in results.results:
            title = r.title or "Ismeretlen forrás"
            url = r.url or ""
            summary = (r.summary or "").strip()
            content = (r.text or "").strip()
            block = f"- Cím: {title}\n  URL: {url}\n  Kivonat: {summary or content[:500]}"
            snippets.append(block)
        if not snippets:
            return ""
        context = (
            "Külső keresési kivonatok (Exa):\n"
            + "\n".join(snippets[:max_results])
            + "\n---\n"
        )
        return context
    except Exception as e:
        print(f"Exa hiba: {e}")
        return ""

# SSE stream a Cerebras gpt-oss-120b-től
async def cerebras_stream(messages: List[Dict[str, str]]):

    # Paraméterek: „maxra” optimalizált, mégis biztonságos
    # Nagy stream tokenlimit, alacsony T, alacsony top_p a stabil válaszért
    stream = cerebras_client.chat.completions.create(
        messages=messages,
        model="gpt-oss-120b",
        stream=True,
        max_completion_tokens=65536,
        temperature=0.13,
        top_p=0.05,
    )

    # A Cerebras SDK szinkron streamet ad vissza; futtasd szálon kívül, ha kell.
    # Itt egyszerűen átközvetítjük SSE-n.
    try:
        for chunk in stream:
            delta = chunk.choices[0].delta.content or ""
            if delta:
                yield {"event": "message", "data": delta}
        # Jelzés a stream végéről
        yield {"event": "end", "data": "[[END]]"}
    except Exception as e:
        yield {"event": "error", "data": f"Hiba a stream során: {str(e)}"}

@app.get("/health")
async def health():
    return {"status": "ok"}

@app.post("/chat/stream")
async def chat_stream(request: Request):
    """
    Body JSON:
    {
      "messages": [{"role":"user","content":"..."}],
      "use_exa": true
    }
    """
    try:
        payload = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Érvénytelen JSON.")

    raw_messages: List[Dict[str, str]] = payload.get("messages", [])
    use_exa: bool = bool(payload.get("use_exa", True))

    if not raw_messages or raw_messages[-1].get("role") != "user":
        raise HTTPException(status_code=400, detail="Hiányzik a felhasználói üzenet.")

    user_msg = raw_messages[-1].get("content", "").strip()
    if not user_msg:
        raise HTTPException(status_code=400, detail="Üres üzenet.")

    # Alap rendszerprompt magyarul
    messages: List[Dict[str, str]] = [{"role": "system", "content": SYSTEM_PROMPT}]

    # Exa-kontekstuk befűzése a legutóbbi kérdés elé
    if use_exa:
        context = await exa_search_augmented_context(user_msg, max_results=8)
        if context:
            messages.append({"role": "system", "content": context})

    # Korábbi üzenetek hozzáadása (opcionálisan szűrhető a hossza)
    for m in raw_messages:
        role = m.get("role", "user")
        content = m.get("content", "")
        if content:
            messages.append({"role": role, "content": content})

    async def event_generator():
        async for event in _to_async_generator(cerebras_stream(messages)):
            yield event

    return EventSourceResponse(event_generator())

# Segédfüggvény: szinkron generator -> async generator
async def _to_async_generator(sync_gen):
    loop = asyncio.get_event_loop()
    iterator = iter(sync_gen)
    while True:
        try:
            item = await loop.run_in_executor(None, next, iterator)
            yield item
        except StopIteration:
            break

# Egyszerű nem-stream végpont (opcionális)
@app.post("/chat")
async def chat_once(request: Request):
    """
    Body JSON:
    {
      "messages": [{"role":"user","content":"..."}],
      "use_exa": true
    }
    """
    payload = await request.json()
    raw_messages: List[Dict[str, str]] = payload.get("messages", [])
    use_exa: bool = bool(payload.get("use_exa", True))

    if not raw_messages or raw_messages[-1].get("role") != "user":
        raise HTTPException(status_code=400, detail="Hiányzik a felhasználói üzenet.")

    user_msg = raw_messages[-1].get("content", "").strip()
    if not user_msg:
        raise HTTPException(status_code=400, detail="Üres üzenet.")

    messages: List[Dict[str, str]] = [{"role": "system", "content": SYSTEM_PROMPT}]
    if use_exa:
        context = await exa_search_augmented_context(user_msg, max_results=8)
        if context:
            messages.append({"role": "system", "content": context})
    for m in raw_messages:
        role = m.get("role", "user")
        content = m.get("content", "")
        if content:
            messages.append({"role": role, "content": content})

    # Nem-streamelt egyszeri hívás
    completion = cerebras_client.chat.completions.create(
        messages=messages,
        model="gpt-oss-120b",
        max_completion_tokens=4096,
        temperature=0.13,
        top_p=0.05,
    )

    text = completion.choices[0].message.content
    return JSONResponse({"reply": text})
```

Futtatás helyben:
- uvicorn main:app --host 0.0.0.0 --port 8000 --reload

Telepítés után a frontend a  helyett a saját domainről is kiszolgálható (statikus szerverrel), de fejlesztéshez elég a helyi.

