  <div class="app">
    <header>
      <div class="wrap brand">
        <div class="logo"></div>
        <div>Magyar AI Chat</div>
        <div class="beta">Cerebras • Exa</div>
      </div>
    </header>

    <main>
      <div class="messages" id="messages"></div>

      <div class="toggles">
        <label class="switch">
          <input type="checkbox" id="exaToggle" checked />
          <span>Exa keresés</span>
        </label>
        <span class="hint">Gyors, élénk pink élmény • Telepíthető PWA iOS-re</span>
      </div>

      <div class="composer">
        <textarea id="input" rows="1" placeholder="Írj ide egy kérdést… (Küldés: Ctrl/Cmd+Enter)"></textarea>
        <button class="send" id="sendBtn">Küldés</button>
      </div>
    </main>
  </div>

  <script>
    // PWA service worker (opcionális, ha külön fájl: sw.js)
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.register('sw.js').catch(()=>{});
    }

    const messagesEl = document.getElementById('messages');
    const inputEl = document.getElementById('input');
    const sendBtn = document.getElementById('sendBtn');
    const exaToggle = document.getElementById('exaToggle');

    let history = [];

    function addBubble(text, role){
      const div = document.createElement('div');
      div.className = 'bubble ' + (role === 'user' ? 'me' : 'ai');
      div.textContent = text;
      messagesEl.appendChild(div);
      messagesEl.scrollTop = messagesEl.scrollHeight;
      return div;
    }

    async function sendMessage(){
      const content = inputEl.value.trim();
      if(!content) return;
      inputEl.value = '';

      history.push({role:'user', content});
      addBubble(content, 'user');

      const aiBubble = addBubble('…', 'assistant');
      aiBubble.textContent = '';

      // SSE streaming
      const useExa = exaToggle.checked;
      const res = await fetch('/chat/stream', {
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ messages: history, use_exa: useExa })
      });

      if (!res.ok) {
        aiBubble.textContent = 'Hiba történt a szerverrel.';
        return;
      }

      const reader = res.body.getReader();
      const decoder = new TextDecoder('utf-8');

      let buffer = '';
      while(true){
        const {done, value} = await reader.read();
        if(done) break;
        const chunk = decoder.decode(value, {stream:true});
        buffer += chunk;

        // SSE formátum feldolgozás
        const lines = buffer.split('\n');
        for (let i=0; i<lines.length-1; i++){
          const line = lines[i].trim();
          if(!line) continue;
          if(line.startsWith('data:')){
            const data = line.slice(5).trim();
            try{
              const evt = JSON.parse(data);
              if(evt.data === '[[END]]'){
                // befejezés
              } else {
                aiBubble.textContent += evt.data;
              }
              messagesEl.scrollTop = messagesEl.scrollHeight;
            }catch(e){
              // ha nem JSON, lehet valami más – kihagyjuk
            }
          }
        }
        buffer = lines[lines.length-1];
      }

      history.push({role:'assistant', content: aiBubble.textContent});
    }

    sendBtn.addEventListener('click', sendMessage);
    inputEl.addEventListener('keydown', (e)=>{
      if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
        sendMessage();
      }
    });

    // Dev szerver esetén állítsd át a backend alap URL-t:
    // fetch('', ...) és engedélyezd CORS-ot.
  </script>
</body>
