import os
import requests
from fastapi import FastAPI, Request, HTTPException
from fastapi.responses import JSONResponse, FileResponse
from fastapi.staticfiles import StaticFiles

app = FastAPI(title="Kép generálás • Imagen 4 Ultra (Gemini)", version="1.0.0")

# Statikus frontend kiszolgálás
app.mount("/", StaticFiles(directory="public", html=True), name="static")

GEMINI_API_KEY = os.environ.get("GEMINI_API_KEY")
IMAGES_ENDPOINT = ""  # Gemini Images API

@app.get("/health")
def health():
    return {"status": "ok"}

@app.post("/image/generate")
async def generate_image(request: Request):
    """
    Body JSON:
    {
      "prompt": "élénk rózsaszín futurisztikus város",
      "size": "1024x1024",
      "num": 1
    }
    """
    if not GEMINI_API_KEY:
        raise HTTPException(status_code=400, detail="Hiányzik a GEMINI_API_KEY (Replit Secrets).")

    try:
        payload = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Érvénytelen JSON.")

    prompt = (payload.get("prompt") or "").strip()
    if not prompt:
        raise HTTPException(status_code=400, detail="Üres prompt.")

    size = (payload.get("size") or "1024x1024").lower()
    if "x" not in size:
        size = "1024x1024"
    try:
        w, h = size.split("x")
        width = max(256, min(2048, int(w)))
        height = max(256, min(2048, int(h)))
    except Exception:
        width, height = 1024, 1024

    num = payload.get("num", 1)
    if not isinstance(num, int) or num < 1 or num > 4:
        num = 1

    body = {
        "model": "imagen-4.0-ultra",
        "prompt": {"text": prompt},
        "image": {"width": width, "height": height},
        "numImages": num
    }

    try:
        resp = requests.post(
            IMAGES_ENDPOINT,
            params={"key": GEMINI_API_KEY},
            headers={"Content-Type": "application/json"},
            json=body,
            timeout=120
        )
        if resp.status_code != 200:
            raise HTTPException(status_code=resp.status_code, detail=f"Gemini Images API hiba: {resp.text}")

        data = resp.json()
        # Példa válasz: {"images":[{"mimeType":"image/png","data":"<base64>"}]}
        images = []
        if isinstance(data, dict) and "images" in data and isinstance(data["images"], list):
            for i, im in enumerate(data["images"], start=1):
                b64 = im.get("data")
                mime = im.get("mimeType", "image/png")
                if b64:
                    images.append({"b64": b64, "mime": mime, "name": f"imagen4_{i}.png"})
        else:
            raise HTTPException(status_code=500, detail="Váratlan API válaszformátum.")

        return JSONResponse({"images": images, "width": width, "height": height})
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Képgenerálási hiba: {str(e)}")
